/*
 AgroSmart Insights - WF0
 Generar fechas para la ingesta historica MIDAGRI MMF2

 Permite:
 - Procesar un mes completo.
 - Probar una fecha especifica.
 - Saltar sabados y domingos.
 - Mantener la fecha dinamica.
*/

const anioTarget = 2026;
const mesTarget = 3;


const resultados = [];

// Validar año y mes.
if (
  !Number.isInteger(anioTarget) ||
  !Number.isInteger(mesTarget) ||
  mesTarget < 1 ||
  mesTarget > 12
) {
  throw new Error('Año o mes invalido');
}

const ultimoDia = new Date(
  Date.UTC(anioTarget, mesTarget, 0)
).getUTCDate();

// Generar fechas.
for (let dia = 1; dia <= ultimoDia; dia++) {

  const fecha = new Date(
    Date.UTC(anioTarget, mesTarget - 1, dia)
  );

  const fechaTexto =
    fecha.toISOString().slice(0, 10);

  const diaSemana = fecha.getUTCDay();

  // Saltar sabados y domingos.
  if (diaSemana === 0 || diaSemana === 6) {
    continue;
  }


  resultados.push({
    json: {
      fecha_objetivo: fechaTexto,
      anio: anioTarget,
      mes: mesTarget
    }
  });
}

// Verificar que exista al menos una fecha.
if (resultados.length === 0) {
  throw new Error(
    'No se generaron fechas. Revisa el mes, año y fechaPrueba.'
  );
}

console.log(
  'Fechas generadas:',
  resultados.map(x => x.json.fecha_objetivo)
);
