const text = $json.text ?? "";

if (!text.trim()) {
  return [];
}

const TAMANO = 1200;
const SOLAPAMIENTO = 200;

const chunks = [];

let inicio = 0;

while (inicio < text.length) {

  const fin = Math.min(inicio + TAMANO, text.length);

  const fragmento = text
    .slice(inicio, fin)
    .trim();

  if (fragmento) {
    chunks.push(fragmento);
  }

  if (fin >= text.length) {
    break;
  }

  inicio = fin - SOLAPAMIENTO;
}


return [{
  json: {
    chunks,
    cantidad_chunks: chunks.length,
    fuente: "MIDAGRI",
    tipo_documento: "boletin_diario",
    mercado: "MMF2",
    fecha: $("Loop Over Items").item.json.fecha_objetivo
  }
}];

const respuesta = $json;

const origen = $("Code - Preparar chunks Jina").item.json;

const chunks = origen.chunks ?? [];
const embeddings = respuesta.data ?? [];

const resultado = [];

for (let i = 0; i < embeddings.length; i++) {

  if (!chunks[i] || !embeddings[i]?.embedding) {
    continue;
  }

  resultado.push({
    json: {
      texto: chunks[i],

      embedding: embeddings[i].embedding,

      metadata: {
        fuente: "MIDAGRI",
        mercado: origen.mercado,
        tipo_documento: "boletin_diario",
        fecha: origen.fecha,
        chunk: i + 1,
        total_chunks: chunks.length,
        modelo_embedding: "jina-embeddings-v3",
        dimensiones: 384
      }
    }
  });
}

return resultado;

/*
 AgroSmart Insights - WF0
 Parser MMF2 - Seleccion por fecha de tabla

 Fuente: MIDAGRI / SISAP

 Objetivos:
 - Leer solo tablas correspondientes al dia solicitado.
 - Evitar mezclar tablas historicas del mismo PDF.
 - Soportar filas horizontales y verticales.
 - Conservar excepcion PERA AGUA ITALIANA.
 - Detectar precios incorrectos y duplicados.
 - NO insertar directamente en PostgreSQL.
*/

const items = $input.all();

const resultados = [];
const errores = [];
const vistos = new Map();

let horizontales = 0;
let verticales = 0;
let duplicadosIdenticos = 0;

// ==========================================
// 1. FECHA SOLICITADA Y FECHA DEL PDF
// ==========================================

const nombrePDF = $('Descargar PDFs')
  .first().binary.data.fileName;

const meses = {
  ene: '01', feb: '02', mar: '03',
  abr: '04', may: '05', jun: '06',
  jul: '07', ago: '08', sep: '09',
  set: '09', oct: '10', nov: '11',
  dic: '12'
};

const coincidencia = nombrePDF.match(
  /^sisap-gmml-mm2-(\d{2})([a-z]{3})(\d{2})\.pdf$/i
);

if (!coincidencia) {
  throw new Error(
    'Nombre del PDF no reconocido: ' + nombrePDF
  );
}

const mesPDF = meses[
  coincidencia[2].toLowerCase()
];

if (!mesPDF) {
  throw new Error('Mes del PDF no reconocido');
}

const fechaObjetivo =
  `20${coincidencia[3]}-${mesPDF}-${coincidencia[1]}`;

const fechaSolicitada = String(
  $('Loop Over Items').item.json.fecha_objetivo ?? ''
).slice(0, 10);

if (
  !fechaSolicitada ||
  fechaObjetivo !== fechaSolicitada
) {
  throw new Error(
    `Fecha incorrecta. PDF: ${fechaObjetivo}. ` +
    `Solicitada: ${fechaSolicitada}`
  );
}

const diaObjetivo = Number(
  fechaObjetivo.slice(8, 10)
);

// ==========================================
// 2. FUNCIONES AUXILIARES
// ==========================================

function normalizarNombre(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();
}

function numero(valor) {
  const texto = String(valor ?? '').trim();

  if (!/^\d+(?:[.,]\d+)?$/.test(texto)) {
    return null;
  }

  const n = Number(texto.replace(',', '.'));

  return Number.isFinite(n) ? n : null;
}

function porcentaje(valor) {
  return /^[-+]?\d+(?:[.,]\d+)?%$/.test(
    String(valor ?? '').trim()
  );
}

function excepcionPera(producto, valores) {
  return (
    fechaObjetivo === '2026-06-24' &&
    normalizarNombre(producto) ===
      'PERA AGUA ITALIANA' &&
    valores.length === 10
  );
}

function validarColumnas(valores, producto) {

  if (valores.length === 12) {

    return (
      porcentaje(valores[2]) &&
      porcentaje(valores[11]) &&
      valores.every((v, i) =>
        i === 2 || i === 11
          ? porcentaje(v)
          : numero(v) !== null
      )
    );
  }

  // Fila excepcional comprobada en el PDF
  // del 24 de junio de 2026.

  if (excepcionPera(producto, valores)) {

    return (
      numero(valores[0]) !== null &&
      valores.slice(1, 9).every(
        v => numero(v) !== null
      ) &&
      porcentaje(valores[9])
    );
  }

  return false;
}

function nombreValido(producto) {

  const nombre = String(producto ?? '').trim();

  if (nombre.length < 3) return false;

  if (/^\d{5}$/.test(nombre)) {
    return false;
  }

  if (/^(GMML|MMF2)$/i.test(nombre)) {
    return false;
  }

  if (/^[-+]?\d+(?:[.,]\d+)?%?$/.test(nombre)) {
    return false;
  }

  if (
    /^\d{5}\s+.+\s+(GMML|MMF2)\s+/i.test(nombre)
  ) {
    return false;
  }

  return true;
}

// ==========================================
// 3. REGISTRAR PRODUCTO
// ==========================================

function registrar({
  codigo,
  producto,
  valores,
  formato
}) {

  const nombre = String(producto ?? '').trim();

  if (!nombreValido(nombre)) {
    errores.push('Producto invalido: ' + nombre);
    return;
  }

  if (!validarColumnas(valores, nombre)) {
    errores.push(
      `Columnas invalidas: ${nombre} -> ` +
      valores.join(' | ')
    );
    return;
  }

  const excepcional = valores.length === 10;

  const precioAyer = numero(
    excepcional ? valores[7] : valores[9]
  );

  const precioHoy = numero(
    excepcional ? valores[8] : valores[10]
  );

  if (
    precioHoy === null ||
    precioHoy <= 0 ||
    precioAyer === null ||
    precioAyer <= 0
  ) {
    errores.push(
      'Precio invalido: ' + nombre
    );
    return;
  }

  const clave = [
    fechaObjetivo,
    'MMF2',
    normalizarNombre(nombre)
  ].join('|');

  if (vistos.has(clave)) {

    const anterior = vistos.get(clave);

    if (
      anterior.precio === precioHoy &&
      anterior.precio_ayer === precioAyer
    ) {
      duplicadosIdenticos++;
      return;
    }

    errores.push(
      `Duplicado contradictorio: ${nombre}. ` +
      `Anterior: ${anterior.precio_ayer}/` +
      `${anterior.precio}. ` +
      `Nuevo: ${precioAyer}/${precioHoy}`
    );

    return;
  }

  vistos.set(clave, {
    precio: precioHoy,
    precio_ayer: precioAyer
  });

  resultados.push({
    json: {
      fecha: fechaObjetivo,
      codigo_cnpa: codigo ?? null,
      producto: nombre,
      mercado: 'MMF2',

      unidad: 'Kilogramo',
      equivalencia_kg: 1,

      precio: precioHoy,
      precio_ayer: precioAyer,

      volumen_t: null,
      volumen_kg: null,

      fuente: 'MIDAGRI',
      formato_origen: formato,
      tipo_prueba: 'parser_mmf2'
    }
  });

  if (formato === 'horizontal') {
    horizontales++;
  } else {
    verticales++;
  }
}

// ==========================================
// 4. DIVIDIR EL PDF EN TABLAS
// ==========================================

function obtenerLineas() {

  const texto = items
    .map(item => String(item.json.text ?? ''))
    .join('\n');

  if (!texto.trim()) {
    throw new Error(
      'Extract from File1 no entrego texto'
    );
  }

  return texto
    .split(/\r?\n/)
    .map(linea =>
      linea.replace(/\s+/g, ' ').trim()
    )
    .filter(Boolean);
}

const lineas = obtenerLineas();

// Ubicar encabezados de tablas de precios.
const inicios = [];

for (let i = 0; i < lineas.length; i++) {

  if (
    /PRECIOS MAYORISTAS DE LOS PRINCIPALES/i
      .test(lineas[i])
  ) {
    inicios.push(i);
  }
}

if (inicios.length === 0) {
  throw new Error(
    'No se encontraron encabezados de tablas de precios'
  );
}

// ==========================================
// 5. IDENTIFICAR FECHA DE CADA TABLA
// ==========================================

function fechaCierreTabla(bloque) {

  // El encabezado contiene los dias
  // de las columnas, por ejemplo:
  // mar-23, mie-24, ..., mar-30.
  //
  // Buscamos el ultimo dia del encabezado,
  // no las fechas de los productos.

  const encabezado = [];

  for (
    let i = 0;
    i < Math.min(bloque.length, 100);
    i++
  ) {

    const linea = bloque[i];

    // Detener al encontrar la primera
    // fila horizontal de producto.
    if (
      /^\d{5}\s+.+?\s+(GMML|MMF2)\s+/i
        .test(linea)
    ) {
      break;
    }

    encabezado.push(linea);
  }

  const texto = encabezado.join(' ');

  const patron =
    /\b(lun|mar|mie|mié|jue|vie|sab|sáb|dom)[-\s]+(\d{1,2})\b/gi;

  const coincidencias = [
    ...texto.matchAll(patron)
  ];

  if (coincidencias.length === 0) {
    return null;
  }

  return Number(
    coincidencias[coincidencias.length - 1][2]
  );
}

// Crear secciones delimitadas por encabezados.
const secciones = [];

for (let i = 0; i < inicios.length; i++) {

  const inicio = inicios[i];

  const fin = (
    i + 1 < inicios.length
      ? inicios[i + 1]
      : lineas.length
  );

  const bloque = lineas.slice(inicio, fin);

  const diaCierre =
    fechaCierreTabla(bloque);

  secciones.push({
    inicio: inicio + 1,
    fin,
    diaCierre,
    bloque
  });
}

console.log(
  'Tablas identificadas:',
  secciones.map(s => ({
    inicio: s.inicio,
    fin: s.fin,
    diaCierre: s.diaCierre
  }))
);

// ==========================================
// 6. SELECCIONAR SOLO FECHA OBJETIVO
// ==========================================

const seleccionadas = secciones.filter(
  seccion =>
    seccion.diaCierre === diaObjetivo
);

if (seleccionadas.length === 0) {
  throw new Error(
    `No se encontro una tabla cuyo cierre ` +
    `sea el dia ${diaObjetivo}. ` +
    `Cierres detectados: ` +
    secciones
      .map(s => s.diaCierre ?? 'sin fecha')
      .join(', ')
  );
}

// Esta comprobacion evita mezclar
// secciones antiguas o sin fecha.

console.log(
  'Fecha objetivo:',
  fechaObjetivo
);

console.log(
  'Secciones seleccionadas:',
  seleccionadas.length
);

// ==========================================
// 7. EXTRAER FILAS HORIZONTALES
// ==========================================

for (const seccion of seleccionadas) {

  const bloque = seccion.bloque;

  for (const linea of bloque) {

    const m = linea.match(
      /^(\d{5})\s+(.+?)\s+MMF2\s+(.+)$/i
    );

    if (!m) continue;

    const codigo = m[1];
    const producto = m[2];

    const valores = m[3]
      .trim()
      .split(/\s+/);

    registrar({
      codigo,
      producto,
      valores,
      formato: 'horizontal'
    });
  }


  // ========================================
  // 8. EXTRAER FILAS VERTICALES
  // ========================================

  for (let i = 0; i < bloque.length; i++) {

    if (bloque[i].toUpperCase() !== 'MMF2') {
      continue;
    }

    const producto = bloque[i - 1] ?? '';


    // Evitar interpretar como vertical una fila
    // que ya contiene todos los datos horizontalmente.
    const filaHorizontal =
      /^\d{5}\s+.+\s+MMF2\s+\d/i.test(producto);

    if (filaHorizontal) {
      continue;
    }

    // Validar que el nombre sea independiente,
    // no una fila horizontal completa.
    if (/^\d{5}\s+.+\s+MMF2\b/i.test(producto)) {
      continue;
    }

    if (!nombreValido(producto)) {
      continue;
    }

    const normalizado = normalizarNombre(producto);

    const clave = [
      fechaObjetivo,
      'MMF2',
      normalizado
    ].join('|');

    // Evitar duplicar una fila ya recuperada.
    if (vistos.has(clave)) {
      continue;
    }

    const valores12 = bloque.slice(i + 1, i + 13);

    let valores = null;

    // CASO NORMAL: 12 columnas
    if (
      valores12.length === 12 &&
      valores12.every(v => !/\s/.test(v)) &&
      validarColumnas(valores12, producto)
    ) {
      valores = valores12;
    }

    // CASO ESPECIAL: PERA AGUA ITALIANA
    if (
      !valores &&
      fechaObjetivo === '2026-06-24' &&
      normalizado === 'PERA AGUA ITALIANA'
    ) {

      const valores10 = bloque.slice(i + 1, i + 11);

      if (
        valores10.length === 10 &&
        valores10.every(v => !/\s/.test(v)) &&
        validarColumnas(valores10, producto)
      ) {
        valores = valores10;
      }
    }

    // CASO ESPECIAL: COCO, MAYO 2026
    if (
      !valores &&
      fechaObjetivo === '2026-05-14' &&
      /^COCO\s*\(COSTA\s*\/\s*SELVA\)$/i.test(producto)
    ) {

      const valores11 = bloque.slice(i + 1, i + 12);

      const valoresEsperados = [
        '0.00',
        '1.81',
        '0.00',
        '0.00',
        '2.13',
        '2.10',
        '2.15',
        '2.10',
        '2.10',
        '2.10',
        '0.0%'
      ];

      // Reconocer unicamente el formato
      // exacto observado en el PDF.
      if (
        valores11.length === 11 &&
        valores11.every(
          (v, j) => v === valoresEsperados[j]
        )
      ) {

        // No registrar COCO porque falta
        // una columna y su posicion no
        // puede reconstruirse con certeza.
        console.log(
          'COCO 2026-05-14: fila incompleta, ' +
          'omitida para evitar precios incorrectos'
        );

        continue;
      }
    }

    if (!valores) {
      errores.push(
        `Fila vertical no interpretable: ${producto}`
      );
      continue;
    }

    const codigoAnterior = bloque[i - 2] ?? '';

    const codigo = /^\d{5}$/.test(codigoAnterior)
      ? codigoAnterior
      : null;

    registrar({
      codigo,
      producto,
      valores,
      formato: 'vertical'
    });
  }
}

